pub const fn registry_entry(id: SimId) -> &'static SimRegistryEntry {
    match id {
        SimId::Blackhole => &SIM_REGISTRY[0],
        SimId::Wormhole => &SIM_REGISTRY[1],
        SimId::BinaryBh => &SIM_REGISTRY[2],
        SimId::WarpDrive => &SIM_REGISTRY[3],
        SimId::Supernova => &SIM_REGISTRY[4],
        SimId::Pulsar => &SIM_REGISTRY[5],
        SimId::Starflight => &SIM_REGISTRY[6],
    }
}

pub fn resolve_sim_id(raw: &str) -> Option<SimId> {
    let key = raw.trim().to_ascii_lowercase();
    for entry in &SIM_REGISTRY {
        if entry.aliases.iter().any(|&a| a == key) {
            return Some(entry.id);
        }
    }
    None
}
